import{_ as e,c as s,o as n,a7 as t}from"./chunks/framework.DPTpzYjp.js";const u=JSON.parse('{"title":"路网相关","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/tech-spec/ros_msgs/route.md","filePath":"orbitcontrol/tech-spec/ros_msgs/route.md"}'),o={name:"orbitcontrol/tech-spec/ros_msgs/route.md"};function i(l,a,p,r,d,c){return n(),s("div",null,a[0]||(a[0]=[t(`<h1 id="路网相关" tabindex="-1">路网相关 <a class="header-anchor" href="#路网相关" aria-label="Permalink to &quot;路网相关&quot;">​</a></h1><blockquote><p>路网（Route Graph）指导导航系统按虚拟路径移动：节点（waypoint/充电点/电梯点/ 停靠点）+ 有向边（行进方向/限速/几何形状）+ 区域（禁行区/缓行区）。</p><p>消息命名说明：本定义的 RouteNode/RouteEdge 与 nav2_msgs 同名消息是<strong>不同包下 的独立定义</strong>（命名空间天然区分），字段为项目定制（方向、几何、限速等）。</p></blockquote><h2 id="设计参考" tabindex="-1">设计参考 <a class="header-anchor" href="#设计参考" aria-label="Permalink to &quot;设计参考&quot;">​</a></h2><p>本接口设计参考了以下系统，后续扩展（新节点类型、新区域类型、新边属性）时 建议先对照参考系统的既有做法，保持延续性：</p><table tabindex="0"><thead><tr><th>参考系统</th><th>借鉴内容</th></tr></thead><tbody><tr><td><a href="https://github.com/ros-navigation/navigation2/tree/main/nav2_msgs" target="_blank" rel="noreferrer">nav2_msgs Route</a>（ROS2 导航）</td><td>Route/RouteNode/RouteEdge 核心拓扑（seq/位置/端点）；SpeedLimit 的 <code>percentage + value</code> 语义（0 为不限速）</td></tr><tr><td><a href="https://github.com/open-rmf/rmf_traffic" target="_blank" rel="noreferrer">Open-RMF building map</a>（多机器人调度）</td><td>节点类型化（charger/dock/holding point）、边方向（bidirectional/orientation）、lane speed_limit、电梯（lift）概念</td></tr><tr><td><a href="https://mavlink.io/en/services/fence.html" target="_blank" rel="noreferrer">MAVLink fence</a>（无人机地理围栏）</td><td>区域几何模型：polygon / circle 两种形状</td></tr><tr><td><a href="https://docs.nav2.org/configuration/packages/costmap-plugins/filters.html" target="_blank" rel="noreferrer">nav2 costmap filters</a></td><td>区域语义：KeepoutFilter（禁行区）、SpeedFilter（缓行区）</td></tr></tbody></table><h2 id="interface-definitions" tabindex="-1">Interface Definitions <a class="header-anchor" href="#interface-definitions" aria-label="Permalink to &quot;Interface Definitions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>数据定义</th><th>描述</th></tr></thead><tbody><tr><td>/set_route_graph</td><td>service</td><td><a href="#setroutegraph">SetRouteGraph</a></td><td>下发路网（全量覆盖设备当前图）</td></tr></tbody></table><h2 id="service-definitions" tabindex="-1">Service Definitions <a class="header-anchor" href="#service-definitions" aria-label="Permalink to &quot;Service Definitions&quot;">​</a></h2><h3 id="setroutegraph" tabindex="-1">SetRouteGraph <a class="header-anchor" href="#setroutegraph" aria-label="Permalink to &quot;SetRouteGraph&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RouteGraph graph</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>bool success</span></span>
<span class="line"><span>string message</span></span></code></pre></div><ul><li>平台在「下发路网」操作（<code>POST /route_graphs/{id}/deploy</code>）时调用</li><li>设备应以接收到的图<strong>全量覆盖</strong>当前使用中的路网</li><li>坐标均为 local map 坐标（米/弧度），与当前加载地图一致</li><li>设备校验 <code>graph.map_id</code> 与当前加载地图一致，不一致返回 <code>success = false</code> 并在 <code>message</code> 中说明（路网坐标系以所属地图为准）</li></ul><h2 id="message-definitions" tabindex="-1">Message Definitions <a class="header-anchor" href="#message-definitions" aria-label="Permalink to &quot;Message Definitions&quot;">​</a></h2><h3 id="routegraph" tabindex="-1">RouteGraph <a class="header-anchor" href="#routegraph" aria-label="Permalink to &quot;RouteGraph&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>string name</span></span>
<span class="line"><span>string map_id           # 路网所属地图（设备校验与当前加载地图一致）</span></span>
<span class="line"><span>RouteNode[] nodes</span></span>
<span class="line"><span>RouteEdge[] edges</span></span>
<span class="line"><span>RouteZone[] zones</span></span></code></pre></div><h3 id="routenode" tabindex="-1">RouteNode <a class="header-anchor" href="#routenode" aria-label="Permalink to &quot;RouteNode&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint16 seq              # 图内序号（图内唯一）</span></span>
<span class="line"><span>string node_type        # waypoint | charger | elevator | dock</span></span>
<span class="line"><span>float64 x               # local map 坐标（米）</span></span>
<span class="line"><span>float64 y</span></span>
<span class="line"><span>float64 yaw             # 朝向（弧度）；0 表示无朝向要求（纯路经点）</span></span>
<span class="line"><span>string metadata_json    # 扩展属性（JSON 字符串，无扩展时为空串）</span></span></code></pre></div><ul><li><code>node_type</code>： <ul><li><code>waypoint</code>：普通路经点</li><li><code>charger</code>：充电点（yaw 为入位朝向）</li><li><code>elevator</code>：电梯点（本轮仅标记位置，楼层映射等经 metadata_json 扩展）</li><li><code>dock</code>：停靠点（yaw 为停靠朝向）</li></ul></li></ul><h3 id="routeedge" tabindex="-1">RouteEdge <a class="header-anchor" href="#routeedge" aria-label="Permalink to &quot;RouteEdge&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint16 seq                  # 图内序号</span></span>
<span class="line"><span>uint16 start_node_seq       # 起点节点 seq</span></span>
<span class="line"><span>uint16 end_node_seq         # 终点节点 seq</span></span>
<span class="line"><span>string direction            # forward | backward | bidirectional</span></span>
<span class="line"><span>string geometry_type        # line | bezier</span></span>
<span class="line"><span>float64[] control_points    # bezier 控制点（扁平 [c1x,c1y,c2x,c2y]；line 时为空）</span></span>
<span class="line"><span>float64 speed_limit         # 限速值；0 表示不限速</span></span>
<span class="line"><span>bool speed_limit_percentage # true=百分比（相对设备最大速度），false=绝对值 m/s</span></span>
<span class="line"><span>float64 cost                # 额外通行代价；0 表示无</span></span>
<span class="line"><span>bool blocked                # 封禁（规划时跳过）</span></span>
<span class="line"><span>string metadata_json        # 扩展属性（JSON 字符串）</span></span></code></pre></div><ul><li><code>direction</code>：以 start → end 为正向；<code>backward</code> 表示仅允许 end → start； <code>bidirectional</code> 双向通行</li><li>任意复杂曲线走向通过增加中间 waypoint 节点 + 多段边表达</li></ul><h3 id="routezone" tabindex="-1">RouteZone <a class="header-anchor" href="#routezone" aria-label="Permalink to &quot;RouteZone&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>string zone_type            # keepout | slow_down</span></span>
<span class="line"><span>string shape                # polygon | circle</span></span>
<span class="line"><span>float64[] points            # polygon 顶点（扁平 [x1,y1,x2,y2,...]）；circle 圆心 [x,y]</span></span>
<span class="line"><span>float64 radius              # circle 半径（米）；polygon 时为 0</span></span>
<span class="line"><span>float64 speed_limit         # 仅 slow_down：限速值</span></span>
<span class="line"><span>bool speed_limit_percentage # 仅 slow_down</span></span>
<span class="line"><span>string metadata_json        # 扩展属性（JSON 字符串）</span></span></code></pre></div><ul><li><code>keepout</code>：禁行区，规划与行驶均不得进入；设备端栅格化进 costmap</li><li><code>slow_down</code>：缓行区，区内按 speed_limit 限速</li></ul>`,23)]))}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
